import{_ as c,l as d,o as a,c as l,v as r,p as s,x as o,d as i,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"brk 与堆","description":"","frontmatter":{"title":"brk 与堆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/brk-heap.md","filePath":"cs/brk-heap.md","lastUpdated":1789023840000}'),m={name:"cs/brk-heap.md"};function h(b,e,k,_,f,u){const t=d("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="brk-与堆" tabindex="-1">brk 与堆 <a class="header-anchor" href="#brk-与堆" aria-label="Permalink to &quot;brk 与堆&quot;">​</a></h1><div class="epigraph"><p>堆是用户空间里一块可伸缩的匿名区；brk 移动它的尽头，并不立刻为每一页准备物理帧。</p><footer>—— 据 Bach, The Design of the UNIX Operating System；Silberschatz et al. 整理</footer></div><p><a href="/cs/user-kernel-split">上一课</a>钉死用户/内核分界。<a href="/cs/addrspace-layout">地址空间布局</a>说堆向高处长，还没有系统调用。<a href="/cs/process-image">进程映像</a>的数据段之后那块空地，程序用 <code>malloc</code> 去填。缺口是内核看见的对象：<strong>program break</strong>，以及它只画出合法虚区间。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若 <code>malloc</code> 每次向内核要一页物理内存，小对象会把系统调用打爆。若把整块堆一次配满物理页，虚大于物的后课策略没有空间。Unix 的选择：<code>brk</code>/<code>sbrk</code> 只改「堆尽头」这个水位；页表项可以仍无效。用户堆分配器在水位以内切块。缺口不是<a href="/cs/paging-vm">分页</a>怎么填，而是谁有权把水位推高，以及推高后访问尚未备份的页会怎样——下一课才按需补页。</p><p>本课不把 glibc 的 arena 与 tcache 写成用户态教材。</p><p><span class="marginnote">当代 libc 大块常用匿名 <code>mmap</code>，小块仍可能走 <code>brk</code>。对内核，二者都是匿名 VMA；本课以 break 为原型，映射区留给 mmap 课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>brk</code> 把水位改到新地址：升高则增加合法区间，降低则放弃高端页（可拆页表）。内核检查不与栈、映射区、内核分界重叠，并受 <code>RLIMIT_DATA</code> 一类配额约束。此刻许多新页仍无帧。用户访问才触发缺页——那是下一课。<code>malloc</code> 失败可以是水位不许再升，也可以是稍后缺页时没有帧。</p>',9)),(a(),s(p,null,{default:o(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MALLOC%5B%22malloc%22%5D%20--%3E%20BRK%5B%22brk%20%E5%8D%87%E6%B0%B4%E4%BD%8D%22%5D%0A%20%20BRK%20--%3E%20VMA%5B%22%E5%90%88%E6%B3%95%E5%8C%BF%E5%90%8D%E5%8C%BA%E9%97%B4%22%5D%0A%20%20VMA%20--%3E%20TOUCH%5B%22%E8%AE%BF%E9%97%AE%3A%20%E5%90%8E%E8%AF%BE%E7%BC%BA%E9%A1%B5%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>堆把「语言运行时的对象图」接到 OS 的匿名区：GC 仍在用户态切块，内核只认 VMA。水位是进程私有的，<code>fork</code> 后各自一份；物理帧是否共享是后课 COW。与<a href="/cs/addrspace-layout">栈</a>对照：栈可在故障时自动向下扩一页，堆通常要显式 <code>brk</code> 或 <code>mmap</code>，免得无意触碰把水位推过栈。</p><p>本课只保证：合法区间集合里多了一段匿名堆。帧从哪来、是否先填零，按需调页回答。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>mallopt</code> 与 arena 调参，不把内核的 <code>vm_brk</code> 实现细节当考纲。也不把文件映射的堆（少见）写成默认。用户把 break 降到仍有指针指向的区域，是程序自己的释放协议，内核不追踪对象图。</p><p>后课默认：堆尽头已是合法虚地址。第一次访问这些页时如何分配帧，下一课按需调页。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>brk</code> 移动堆水位，画出合法匿名区间。</li><li>多数新页此刻无物理帧；补页是下一课。</li><li>大块匿名映射与 <code>brk</code> 同属匿名区，细节在 mmap。</li><li>出处：Bach, <em>UNIX</em>；Silberschatz et al., <em>OSC</em>；Tanenbaum <em>MOS</em>。</li></ul>',8))])}const B=c(m,[["render",h]]);export{A as __pageData,B as default};
